import pyomo.environ as pyo

DATA = {
    "water_per_bag": {"subsoil": 10, "topsoil": 6},   # units of water per bag per day
    "total_bag_limit": 150,                           # combined truck capacity (bags)
    "min_topsoil_bags": 10,                           # at least 10 bags of topsoil
    "max_topsoil_fraction": 0.30,                     # topsoil <= 30% of all bags
}


def build_model(data=None):
    d = data or DATA
    soil_rates = d["water_per_bag"]

    model = pyo.ConcreteModel()

    # Set of soil types
    model.SOILS = pyo.Set(initialize=list(soil_rates.keys()))

    # Decision variable: integer number of bags bought for each soil type
    def x_bounds(m, s):
        return (0, None)

    model.x = pyo.Var(model.SOILS, within=pyo.NonNegativeIntegers, bounds=x_bounds)

    # Objective: minimize total daily water required to hydrate the bed
    def obj_rule(m):
        return sum(soil_rates[s] * m.x[s] for s in m.SOILS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Constraint: combined bags must not exceed truck capacity
    def capacity_rule(m):
        return sum(m.x[s] for s in m.SOILS) <= d["total_bag_limit"]

    model.capacity = pyo.Constraint(rule=capacity_rule)

    # Constraint: at least 10 bags of topsoil  (topsoil >= min)
    def min_topsoil_rule(m):
        return m.x["topsoil"] >= d["min_topsoil_bags"]

    model.min_topsoil = pyo.Constraint(rule=min_topsoil_rule)

    # Constraint: topsoil <= 30% of all bags  ->  0.7*x_topsoil - 0.3*x_subsoil <= 0
    def topsoil_fraction_rule(m):
        f = d["max_topsoil_fraction"]
        return m.x["topsoil"] <= f * (m.x["topsoil"] + m.x["subsoil"])

    model.topsoil_fraction = pyo.Constraint(rule=topsoil_fraction_rule)

    return model


