    "soil_types": ["subsoil", "topsoil"],
    "water_per_bag": {"subsoil": 10, "topsoil": 6},
    "total_bags_max": 150,
    "topsoil_min": 10,
    "topsoil_max_frac": 0.30,
    "bag_upper_bound": 150,
}

