def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.S = pyo.Set(initialize=d["soil_types"], ordered=True)

    model.bags = pyo.Var(
        model.S,
        domain=pyo.NonNegativeIntegers,
        bounds=(0, d["bag_upper_bound"]),
    )

    def obj_rule(m):
        return sum(d["water_per_bag"][s] * m.bags[s] for s in m.S)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def capacity_rule(m):
        return sum(m.bags[s] for s in m.S) <= d["total_bags_max"]

    model.capacity = pyo.Constraint(rule=capacity_rule)

    def topsoil_min_rule(m):
        return m.bags["topsoil"] >= d["topsoil_min"]

    model.topsoil_min = pyo.Constraint(rule=topsoil_min_rule)

    def topsoil_frac_rule(m):
        return (
            (1 - d["topsoil_max_frac"]) * m.bags["topsoil"]
            - d["topsoil_max_frac"] * m.bags["subsoil"]
            <= 0
        )

    model.topsoil_frac = pyo.Constraint(rule=topsoil_frac_rule)

    return model
